@GameTestHolder("ageofexpansion")
public final class ImageDisplayTests {
    @GameTestGenerator public static Collection<TestFunction> tests(){var tests=new ArrayList<TestFunction>();add(tests,"image_jpeg_source_limit",ImageDisplayTests::jpegSourceLimit);add(tests,"image_storage_migration",ImageDisplayTests::storage);add(tests,"image_scaling_modes",ImageDisplayTests::scaling);add(tests,"image_decode_validation",ImageDisplayTests::decode);add(tests,"image_paint_undo",ImageDisplayTests::paint);add(tests,"image_library_permissions_delete",ImageDisplayTests::permissions);add(tests,"image_modules_isolation",ImageDisplayTests::modules);add(tests,"image_upload_atomic",ImageDisplayTests::upload);add(tests,"image_recipes_and_models",ImageDisplayTests::recipes);add(tests,"image_network_limits_cancel",ImageDisplayTests::networkLimits);add(tests,"image_download_cancel_fairness",ImageDisplayTests::downloadQueue);return tests;}
    private static void add(List<TestFunction> list,String name,java.util.function.Consumer<GameTestHelper> test){list.add(new TestFunction("ageofexpansion:images","ageofexpansion:"+name,"ageofexpansion:module_empty",4000,0,true,test));}
    public static BufferedImage sample(){var image=new BufferedImage(32,16,BufferedImage.TYPE_INT_ARGB);for(int y=0;y<16;y++)for(int x=0;x<32;x++)image.setRGB(x,y,0xff000000|x*8<<16|y*16<<8|0x66);return image;}
    private static void jpegSourceLimit(GameTestHelper h){try{
        var photo=new BufferedImage(768,768,BufferedImage.TYPE_INT_RGB);var random=new Random(20260914);for(int y=0;y<768;y++)for(int x=0;x<768;x++)photo.setRGB(x,y,random.nextInt(0x1000000));
        var stream=new ByteArrayOutputStream();javax.imageio.ImageIO.write(photo,"jpeg",stream);byte[] source=stream.toByteArray();var decoded=ImageFiles.decode(source);
        h.assertTrue(source.length<1024*1024&&decoded.png().length>1024*1024,"JPEG below 1MB may become a PNG above 1MB");
        var pos=h.absolutePos(new BlockPos(7,8,8));var be=place(h,pos,block(1));var player=player(h,pos,false);var library=ImageLibrary.get(h.getLevel());ImageNetwork.open(player,be);UUID token=token(player),request=UUID.randomUUID();var n=new CompoundTag();n.putString("name","JPEG source limit regression");int parts=(source.length+ImageNetwork.PART-1)/ImageNetwork.PART;
        for(int i=0;i<parts;i++)send(player,new ImageNetwork.Frame(ImageNetwork.UPLOAD,request,token,n,i,parts,Arrays.copyOfRange(source,i*ImageNetwork.PART,Math.min(source.length,(i+1)*ImageNetwork.PART))));
        h.succeedWhen(()->{h.assertTrue(library.count(player.getUUID())==1,"Source-size upload limit accepts compressed JPEG");var entry=library.list(player,"").getFirst();try{long cached=java.nio.file.Files.size(ImageStore.blob(ImageLibrary.directory(h.getLevel()),library.asset(entry.id()).full().digest()));h.assertTrue(cached<=source.length&&library.asset(entry.id()).full().codec().equals("jpeg"),"JPEG storage retains verified original scan data without PNG expansion");com.tajlpawa.ageofexpansion.AgeofExpansion.LOGGER.info("JPEG_SOURCE_LIMIT_PASSED source_bytes={} stored_jpeg_bytes={}",source.length,cached);}catch(IOException e){throw new RuntimeException(e);}});
    }catch(Exception e){throw new RuntimeException(e);}}
    private static void storage(GameTestHelper h){try{
        UUID id=UUID.randomUUID();var legacy=ImageStorage.root().resolve("test-legacy-"+id);var target=ImageStorage.originals(UUID.randomUUID());
        ImageFiles.atomicWrite(ImageLibrary.file(legacy,id,false),ImageFiles.png(sample()));
        byte[] thumb=ImageStorage.readOriginal(target,legacy,id,true);
        h.assertTrue(java.nio.file.Files.exists(ImageLibrary.file(target,id,false))&&java.nio.file.Files.exists(ImageLibrary.file(target,id,true)),"Requesting legacy thumbnail migrates both original and thumbnail");
        h.assertTrue(java.nio.file.Files.exists(ImageLibrary.file(legacy,id,false))&&ImageFiles.decode(thumb).visible(),"Legacy original retained and migrated thumbnail is valid");
        h.assertTrue(ImageLibrary.directory(h.getLevel()).startsWith(net.neoforged.fml.loading.FMLPaths.GAMEDIR.get().resolve("ageofexpansion_image_cache")),"Server originals belong to the game root cache");
        var tag=ImageLibrary.get(h.getLevel()).save(new CompoundTag(),h.getLevel().registryAccess());h.assertTrue(ImageLibrary.load(tag,h.getLevel().registryAccess()).save(new CompoundTag(),h.getLevel().registryAccess()).getUUID("storageId").equals(tag.getUUID("storageId")),"Storage namespace survives save reload");
        for(var file:new java.nio.file.Path[]{ImageLibrary.file(legacy,id,false),ImageLibrary.file(target,id,false),ImageLibrary.file(target,id,true)})java.nio.file.Files.deleteIfExists(file);java.nio.file.Files.deleteIfExists(legacy);java.nio.file.Files.deleteIfExists(target);h.succeed();
    }catch(Exception e){throw new RuntimeException(e);}}
    private static void scaling(GameTestHelper h){int count=0;for(boolean fit:new boolean[]{false,true})for(int scale:new int[]{1,25,100,400,1000})for(int align=0;align<3;align++)for(int vertical=0;vertical<3;vertical++)for(int[] size:new int[][]{{32,16},{16,32},{64,64}}){
        var value=new ImageSelection(UUID.randomUUID(),scale,align,vertical,fit);for(float[] screen:new float[][]{{120,60},{108,108},{396,252}}){var r=value.layout(size[0],size[1],screen[0],screen[1]);h.assertTrue(r.x()>=0&&r.y()>=0&&r.x()+r.width()<=screen[0]+.001&&r.y()+r.height()<=screen[1]+.001,"Image never exceeds screen");h.assertTrue(r.u0()>=-.001&&r.v0()>=-.001&&r.u1()<=1.001&&r.v1()<=1.001,"UV crop valid");if(fit)h.assertTrue(r.u0()==0&&r.v0()==0&&Math.abs(r.u1()-1)<.001&&Math.abs(r.v1()-1)<.001,"Fit retains full image");if(align==1)h.assertTrue(Math.abs(r.x()+r.width()/2-screen[0]/2)<.001,"Horizontal centering");count++;}h.assertTrue(ImageSelection.load(value.save()).equals(value)&&value.scale()==scale,"Mode and target persist independently");}
        com.tajlpawa.ageofexpansion.AgeofExpansion.LOGGER.info("IMAGE_LAYOUT_PASSED: {} mode/scale/alignment/aspect cases",count);h.succeed();}
    private static void decode(GameTestHelper h){try{
        var png=ImageFiles.png(sample());var decoded=ImageFiles.decode(png);h.assertTrue(decoded.visible()&&decoded.image().getWidth()==32&&decoded.image().getHeight()==16,"PNG dimensions and visibility");
        h.assertTrue(!ImageFiles.decode(ImageFiles.png(new BufferedImage(16,16,BufferedImage.TYPE_INT_ARGB))).visible(),"Fully transparent image is unlit");
        var rgb=new BufferedImage(16,16,BufferedImage.TYPE_INT_RGB);var jpeg=new ByteArrayOutputStream();javax.imageio.ImageIO.write(rgb,"jpeg",jpeg);h.assertTrue(ImageFiles.decode(jpeg.toByteArray()).visible(),"JPEG accepted and normalized");
        boolean bad=false;try{ImageFiles.decode(new byte[20]);}catch(IOException e){bad=true;}h.assertTrue(bad,"Malformed image rejected");bad=false;try{ImageFiles.decode(ImageFiles.png(new BufferedImage(2049,1,BufferedImage.TYPE_INT_ARGB)));}catch(IOException e){bad=true;}h.assertTrue(bad,"Dimensions checked before large pixel decode");h.succeed();
    }catch(IOException e){throw new RuntimeException(e);}}
    private static void paint(GameTestHelper h){try(var canvas=new PaintCanvas(new BufferedImage(32,32,BufferedImage.TYPE_INT_ARGB),2,1)){
        canvas.begin(4.2,4.2,1,0xff0000,50,false);for(int i=0;i<4;i++)canvas.drag(4.2,4.2);canvas.end();int pixel=canvas.image.getRGB(4,4);h.assertTrue((pixel>>>24)==128,"Half opacity does not accumulate within a stroke");
        canvas.begin(4.2,4.2,1,0,100,true);canvas.end();h.assertTrue(canvas.image.getRGB(4,4)>>>24==0,"Eraser clears alpha");canvas.undo();h.assertTrue(canvas.image.getRGB(4,4)==pixel,"Disk-spilled undo restores exact pixels");canvas.undo();h.assertTrue(canvas.image.getRGB(4,4)==0,"Undo to transparent origin");
        for(int n=0;n<3;n++){canvas.begin(1,1,1,0x00ff00+n,100,false);canvas.drag(20,1);canvas.end();}h.assertTrue(canvas.undoCount()==2,"Undo count bounded");for(int x=1;x<=20;x++)h.assertTrue(canvas.image.getRGB(x,1)>>>24==255,"Interpolated stroke has no gaps");
        try(var noUndo=new PaintCanvas(sample(),0)){noUndo.begin(1,1,512,0,100,true);noUndo.end();h.assertTrue(!noUndo.undo()&&noUndo.undoCount()==0,"Undo disabled at zero");}h.succeed();
    }catch(IOException e){throw new RuntimeException(e);}}
    private static DisplayBlock block(int kind){return (kind==0?DisplayContent.IMAGE:kind==1?DisplayContent.IMAGE_SQUARE:DisplayContent.IMAGE_MODULE).get();}
    private static DisplayBlockEntity place(GameTestHelper h,BlockPos p,DisplayBlock block){h.getLevel().setBlockAndUpdate(p.south(),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(p,block.defaultBlockState());var be=(DisplayBlockEntity)h.getLevel().getBlockEntity(p);if(block.kind==2){var store=ModuleScreens.get(h.getLevel());store.register(h.getLevel(),be);store.tick(h.getLevel());}ImageLibrary.get(h.getLevel()).watch(be);return be;}
    private static ServerPlayer player(GameTestHelper h,BlockPos p,boolean admin){var player=new net.neoforged.neoforge.common.util.FakePlayer(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),admin?"ImageAdmin":"ImageOwner")){@Override public boolean hasPermissions(int level){return admin||level==0;}};player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.setPos(p.getX()+.5,p.getY(),p.getZ()-1);return player;}
    private static ImageLibrary.Entry entry(ServerPlayer owner){return new ImageLibrary.Entry(UUID.randomUUID(),owner.getUUID(),owner.getGameProfile().getName(),"Image",32,16,true);}
    private static UUID token(ServerPlayer p){try{var field=ImageNetwork.class.getDeclaredField("SESSIONS");field.setAccessible(true);var session=((Map<?,?>)field.get(null)).get(p.getUUID());var method=session.getClass().getDeclaredMethod("token");method.setAccessible(true);return (UUID)method.invoke(session);}catch(Exception e){throw new RuntimeException(e);}}
    private static void send(ServerPlayer p,ImageNetwork.Frame frame){try{var method=ImageNetwork.class.getDeclaredMethod("server",ServerPlayer.class,ImageNetwork.Frame.class);method.setAccessible(true);method.invoke(null,p,frame);}catch(Exception e){throw new RuntimeException(e);}}
    private static void control(ServerPlayer p,int action,UUID token,CompoundTag data){send(p,new ImageNetwork.Frame(action,UUID.randomUUID(),token,data,0,1,new byte[0]));}
    private static boolean pending(String field,UUID player){try{var f=ImageNetwork.class.getDeclaredField(field);f.setAccessible(true);return ((Map<?,?>)f.get(null)).containsKey(player);}catch(Exception e){throw new RuntimeException(e);}}
    private static void networkLimits(GameTestHelper h){try{
        var pos=h.absolutePos(new BlockPos(7,8,8));var be=place(h,pos,block(0));var p=player(h,pos,false);var admin=player(h,pos,true);var library=ImageLibrary.get(h.getLevel());ImageNetwork.open(p,be);ImageNetwork.open(admin,be);UUID token=token(p);byte[] bytes=ImageFiles.png(sample());var data=new CompoundTag();
        int normalLimit=Config.PLAYER_IMAGES.get(),adminLimit=Config.ADMIN_IMAGES.get(),sizeLimit=Config.IMAGE_KB.get();
        try{
            Config.PLAYER_IMAGES.set(0);Config.ADMIN_IMAGES.set(0);
            for(var who:List.of(p,admin))send(who,new ImageNetwork.Frame(ImageNetwork.UPLOAD,UUID.randomUUID(),token(who),data,0,1,bytes));
            h.assertTrue(!pending("IN",p.getUUID())&&!pending("JOBS",p.getUUID())&&!pending("JOBS",admin.getUUID()),"Zero quotas reject ordinary/admin uploads before processing");
            Config.PLAYER_IMAGES.set(normalLimit);Config.ADMIN_IMAGES.set(adminLimit);Config.IMAGE_KB.set(16);
            send(p,new ImageNetwork.Frame(ImageNetwork.UPLOAD,UUID.randomUUID(),token,data,0,1,new byte[16385]));h.assertTrue(!pending("IN",p.getUUID())&&!pending("JOBS",p.getUUID()),"Original upload size enforced");
        }finally{Config.PLAYER_IMAGES.set(normalLimit);Config.ADMIN_IMAGES.set(adminLimit);Config.IMAGE_KB.set(sizeLimit);}
        UUID first=UUID.randomUUID();send(p,new ImageNetwork.Frame(ImageNetwork.UPLOAD,first,token,data,0,2,new byte[8]));h.assertTrue(pending("IN",p.getUUID()),"Partial transfer retained");var cancel=new CompoundTag();cancel.putUUID("request",first);control(p,ImageNetwork.CANCEL,token,cancel);h.assertTrue(!pending("IN",p.getUUID()),"Cancel frees assembly buffer");
        send(p,new ImageNetwork.Frame(ImageNetwork.UPLOAD,first,token,data,1,2,new byte[8]));h.assertTrue(!pending("JOBS",p.getUUID()),"Late fragment cannot revive cancellation");
        UUID order=UUID.randomUUID();send(p,new ImageNetwork.Frame(ImageNetwork.UPLOAD,order,token,data,0,3,new byte[8]));send(p,new ImageNetwork.Frame(ImageNetwork.UPLOAD,order,token,data,2,3,new byte[8]));h.assertTrue(!pending("IN",p.getUUID()),"Out-of-order transfer discarded");
        UUID complete=UUID.randomUUID();send(p,new ImageNetwork.Frame(ImageNetwork.UPLOAD,complete,token,data,0,1,bytes));cancel.putUUID("request",complete);control(p,ImageNetwork.CANCEL,token,cancel);h.assertTrue(!pending("JOBS",p.getUUID()),"Cancel invalidates background commit");
        var otherPos=pos.west();var otherBe=place(h,otherPos,block(1));var other=player(h,otherPos,false);ImageNetwork.open(other,otherBe);UUID otherToken=token(other);send(other,new ImageNetwork.Frame(ImageNetwork.UPLOAD,UUID.randomUUID(),otherToken,data,0,1,bytes));send(other,new ImageNetwork.Frame(ImageNetwork.UPLOAD,UUID.randomUUID(),otherToken,data,0,1,bytes));
        h.succeedWhen(()->{h.assertTrue(library.count(other.getUUID())==1,"Concurrent duplicate upload rejected while first commits");h.assertTrue(library.count(p.getUUID())==0,"Cancelled upload consumes no quota");});
    }catch(Exception e){throw new RuntimeException(e);}}
    private static Object networkField(String name)throws Exception{var field=ImageNetwork.class.getDeclaredField(name);field.setAccessible(true);return field.get(null);}
    private static void downloadQueue(GameTestHelper h){try{
        var pos=h.absolutePos(new BlockPos(7,8,8));var be=place(h,pos,block(0));var p=player(h,pos,false);var other=player(h,pos,false);ImageNetwork.open(p,be);ImageNetwork.open(other,be);UUID token=token(p),request=UUID.randomUUID();
        var transmit=ImageNetwork.class.getDeclaredMethod("send",ServerPlayer.class,ImageNetwork.Packet.class);transmit.setAccessible(true);byte[] body=new byte[ImageNetwork.PART*6];long baseline=(long)networkField("queuedBytes");
        transmit.invoke(null,p,new ImageNetwork.Packet(ImageNetwork.GET,request,token,new CompoundTag(),body));transmit.invoke(null,other,new ImageNetwork.Packet(ImageNetwork.GET,request,token,new CompoundTag(),body));
        var cancel=new CompoundTag();cancel.putUUID("request",request);control(p,ImageNetwork.CANCEL,UUID.randomUUID(),cancel);h.assertTrue(pending("OUT",p.getUUID()),"Wrong token cannot cancel queued download");control(p,ImageNetwork.CANCEL,token,cancel);h.assertTrue(!pending("OUT",p.getUUID())&&pending("OUT",other.getUUID()),"Cancellation affects only the requesting player's queue");h.assertTrue((long)networkField("queuedBytes")==baseline+body.length,"Cancelled download releases byte budget exactly once");ImageNetwork.forget(other.getUUID());h.assertTrue((long)networkField("queuedBytes")==baseline,"Disconnect releases remaining queued bytes");
        var entry=entry(p);var prepared=ImageFiles.prepare(ImageFiles.png(sample()),false);var lib=ImageLibrary.get(h.getLevel());lib.add(entry);lib.attach(entry.id(),ImageStore.put(ImageLibrary.directory(h.getLevel()),entry.id(),prepared));var data=new CompoundTag();data.putUUID("id",entry.id());UUID pending=UUID.randomUUID();send(p,new ImageNetwork.Frame(ImageNetwork.GET,pending,token,data,0,1,new byte[0]));cancel.putUUID("request",pending);control(p,ImageNetwork.CANCEL,token,cancel);h.assertTrue(((Map<?,?>)((Map<?,?>)networkField("DOWNLOADS")).get(p.getUUID())).isEmpty(),"Cancel removes asynchronous read subscription");
        var type=Class.forName(ImageNetwork.class.getName()+"$Sending");var ctor=type.getDeclaredConstructor(ImageNetwork.Packet.class);ctor.setAccessible(true);var packetField=type.getDeclaredField("packet");packetField.setAccessible(true);var queue=new ArrayDeque<Object>();UUID a=UUID.randomUUID(),b=UUID.randomUUID(),background=UUID.randomUUID();for(var id:List.of(a,b,background))queue.add(ctor.newInstance(new ImageNetwork.Packet(ImageNetwork.GET,id,id.equals(background)?ImageSelection.NONE:token,new CompoundTag(),body)));
        var next=ImageNetwork.class.getDeclaredMethod("nextSending",ArrayDeque.class,int.class);next.setAccessible(true);var order=new ArrayList<UUID>();for(int turn=1;turn<=10;turn++){var job=next.invoke(null,queue,turn);order.add(((ImageNetwork.Packet)packetField.get(job)).request());queue.addLast(job);}h.assertTrue(order.equals(List.of(a,b,a,b,background,a,b,a,b,background)),"Interactive downloads rotate fairly while world downloads receive every fifth slot");
        h.runAfterDelay(20,()->{h.assertTrue(!pending("OUT",p.getUUID()),"Late completed read does not resurrect cancelled download");h.succeed();});
    }catch(Exception e){throw new RuntimeException(e);}}
    private static void permissions(GameTestHelper h){
        var pos=h.absolutePos(new BlockPos(7,8,8));var be=place(h,pos,block(0));var own=player(h,pos,false);var other=player(h,pos,false);var admin=player(h,pos,true);var lib=ImageLibrary.get(h.getLevel());var e=entry(own);lib.add(e);
        h.assertTrue(lib.canUse(own,e.id())&&!lib.canUse(other,e.id())&&lib.canUse(admin,e.id()),"Owner/admin authorization");h.assertTrue(lib.list(other,"*").isEmpty()&&lib.list(admin,"*").stream().anyMatch(v->v.id().equals(e.id())),"Ordinary filter cannot expose others' library");
        h.assertTrue(lib.owners(other,"").isEmpty()&&lib.owners(admin,own.getUUID().toString()).stream().anyMatch(o->o.id().equals(own.getUUID())&&o.count()>0),"Owner picker is admin-only and includes offline image owners");h.assertTrue(lib.owners(admin,"no-such-image-owner").isEmpty(),"Unknown owner is not selectable");
        var selection=new ImageSelection(e.id(),400,1,1,true);ImageNetwork.open(other,be);var n=new CompoundTag();n.put("selection",selection.save());control(other,ImageNetwork.APPLY,token(other),n);h.assertTrue(!be.image().present(),"Forged foreign image binding rejected");
        ImageNetwork.open(own,be);control(own,ImageNetwork.APPLY,token(own),n);h.assertTrue(be.image().equals(selection)&&be.getBlockState().getLightEmission(h.getLevel(),pos)==7,"Authorized selection emits level seven");
        ImageNetwork.open(other,be);n.put("selection",new ImageSelection(e.id(),100,0,0,false).save());control(other,ImageNetwork.APPLY,token(other),n);h.assertTrue(be.image().scale()==100,"Existing image may be retained while adjusting display");
        lib.delete(h.getLevel(),e.id());h.assertTrue(!be.image().present()&&!be.getBlockState().getValue(DisplayBlock.LIT),"Deleting image clears loaded references immediately");
        var tag=lib.save(new CompoundTag(),h.getLevel().registryAccess());h.assertTrue(ImageLibrary.load(tag,h.getLevel().registryAccess()).at(e.id())==null,"Deleted image stays absent after reload");h.succeed();
    }
    private static void modules(GameTestHelper h){var p=h.absolutePos(new BlockPos(9,10,8));var store=ModuleScreens.get(h.getLevel());var lib=ImageLibrary.get(h.getLevel());var e=entry(player(h,p,false));lib.add(e);var members=List.of(p,p.west(),p.below(),p.west().below());
        for(var m:members)place(h,m,block(2));place(h,p.east(),DisplayContent.MODULE.get());place(h,p.east().below(),DisplayContent.HOLOGRAPHIC_MODULE.get());store.tick(h.getLevel());var group=store.at(p);h.assertTrue(group.members.size()==4&&group.imageScreen,"Only image modules connect");store.updateImage(h.getLevel(),group,new ImageSelection(e.id(),400,1,1,false));for(var m:members)h.assertTrue(h.getLevel().getBlockState(m).getLightEmission(h.getLevel(),m)==7,"Whole group illuminated");
        var loaded=ModuleScreens.load(store.save(new CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(loaded.at(p).image.equals(group.image)&&loaded.at(p).imageScreen,"Image group settings persist");h.getLevel().setBlockAndUpdate(p.west().below(),Blocks.AIR.defaultBlockState());for(var m:members)if(store.at(m)!=null)h.assertTrue(!store.at(m).image.present(),"Breaking member clears full group reference");h.assertTrue(lib.at(e.id())!=null,"Breaking never deletes library asset");h.succeed();}
    private static void upload(GameTestHelper h){try{
        var pos=h.absolutePos(new BlockPos(7,8,8));var be=place(h,pos,block(1));var p=player(h,pos,false);var library=ImageLibrary.get(h.getLevel());ImageNetwork.open(p,be);UUID token=token(p),request=UUID.randomUUID();byte[] bytes=ImageFiles.png(sample());var meta=new CompoundTag();meta.putString("name","上传测试");
        var frame=new ImageNetwork.Frame(ImageNetwork.UPLOAD,request,token,meta,0,1,bytes);var buf=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{ImageNetwork.Frame.CODEC.encode(buf,frame);send(p,ImageNetwork.Frame.CODEC.decode(buf));}finally{buf.release();}
        h.succeedWhen(()->{h.assertTrue(library.count(p.getUUID())==1,"Complete upload committed once");var e=library.list(p,"").getFirst();h.assertTrue(java.nio.file.Files.exists(ImageStore.blob(ImageLibrary.directory(h.getLevel()),library.asset(e.id()).full().digest())),"Image content saved independently");h.assertTrue(!be.image().present(),"Upload does not change screen until apply");});
    }catch(Exception e){throw new RuntimeException(e);}}
    private static void recipes(GameTestHelper h){var patterns=List.of(List.of(" C ","BAB"," C "),List.of("DCD","BAB","DCD"),List.of(" A ","ABA"," A "));for(int kind=0;kind<3;kind++){
        var map=kind==2?Map.of('A',Items.IRON_INGOT,'B',block(1).asItem()):Map.of('A',Items.BLACK_STAINED_GLASS_PANE,'B',Items.REDSTONE,'C',Items.AMETHYST_SHARD,'D',Items.IRON_INGOT);List<ItemStack> stacks=new ArrayList<>();for(var row:patterns.get(kind))for(char c:row.toCharArray())stacks.add(c==' '?ItemStack.EMPTY:new ItemStack(map.get(c)));var recipe=(CraftingRecipe)h.getLevel().getRecipeManager().byKey(net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(block(kind))).orElseThrow().value();var input=CraftingInput.of(3,3,stacks);h.assertTrue(recipe.matches(input,h.getLevel())&&recipe.assemble(input,h.getLevel().registryAccess()).is(block(kind).asItem()),"Exact image screen recipe");}h.succeed();}
}
